#!/usr/bin/env sh
# Re-vendor third-party code. Pinned, committed, and served directly — these
# run as ES modules in the browser, so there is no bundler and no build step.
# The "build" is this script; its output is checked in.
set -e
cd "$(dirname "$0")"

MOTION_VERSION="11.18.2"

echo "vendoring motion@${MOTION_VERSION} (MIT)"
curl -sSL --retry 3 --retry-delay 2 --max-time 30 \
  "https://cdn.jsdelivr.net/npm/motion@${MOTION_VERSION}/dist/motion.js" -o motion.umd.js.tmp
# strip the sourcemap pointer; the map is not vendored and would 404
sed -e 's|//# sourceMappingURL=.*||' motion.umd.js.tmp > motion.umd.js
rm -f motion.umd.js.tmp

# The dist is UMD. Under a module import there is no `exports` and no `define`,
# so it takes its globalThis branch and publishes globalThis.Motion; this shim
# re-exports that as named ESM bindings.
cat > motion.mjs <<'SHIM'
// Generated by vendor/fetch.sh — do not edit.
//
// The dist is UMD and is invoked with `this`, which is undefined inside an ES
// module. Its own fallback resolves to globalThis, so importing it for side
// effects publishes globalThis.Motion; this shim re-exports those as named
// bindings and degrades to no-ops if it ever fails to load.
import './motion.umd.js';
const M = globalThis.Motion || {};
const noop = () => ({ finished: Promise.resolve(), cancel() {}, stop() {} });
export const ok = typeof M.animate === 'function';
export const animate = M.animate || noop;
export const spring = M.spring || (() => 'ease-out');
export const stagger = M.stagger || (() => 0);
export const inView = M.inView || (() => () => {});
export default M;
SHIM

# ---- typeface
echo "vendoring Inter Variable (OFL-1.1)"
mkdir -p fonts
for f in inter-latin-wght-normal inter-latin-ext-wght-normal; do
  curl -sSL --retry 3 --retry-delay 2 --max-time 40 \
    "https://cdn.jsdelivr.net/npm/@fontsource-variable/inter@5.1.0/files/${f}.woff2" \
    -o "fonts/${f}.woff2"
done

# ---- icons (path data is extracted into ../icons.js by hand; see README)
echo "vendoring lucide icons (ISC) -> ../icons.js"
mkdir -p icons
for n in x chevron-left chevron-right lock lock-open maximize-2 rotate-ccw coffee \
         printer sun moon contrast plus arrow-up arrow-down clipboard-list \
         shuffle triangle-alert info trash-2 circle-alert play \
         grip-vertical share-2 share settings; do
  curl -sSL --retry 3 --retry-delay 2 --max-time 20 \
    "https://cdn.jsdelivr.net/npm/lucide-static@0.460.0/icons/${n}.svg" -o "icons/${n}.svg"
done

